import axios from "axios";
import { useEffect } from "react";

const App = () => {
  useEffect(() => {
    async function getData() {
      try {
        let response = await axios.get("https://jsonplaceholder.typicode.com/users");
        console.log(response.data);
      } catch (error) {
        console.log(error);
      }
    }
    getData();
  }, []);

  return <div>App</div>;
};

export default App;
